t.script:
var kts = document.getElementsByClassName('koroshi-k');
for (var i = 0; kts.length > i; i++) {
    var s = 300;
    kts[i].style.fontSize = s + 'pt';
    while (s > 60) {
        if (kts[i].scrollWidth > kts[i].clientWidth) { s = s - 5; kts[i].style.fontSize = s + 'pt'; } else { break; }
    }
}
